'use strict';
/*
 * register-queue-coverage.js  —  THE STANDING CHECK THE QUEUE DID NOT HAVE
 *
 * `make queue-check` proves that `queue/QUEUE.md` is current with respect to
 * `queue/work-queue.yaml`. That is the edge where staleness is harmless: the
 * generated view is regenerated by one command and nobody plans work from it.
 *
 * The edge that matters had no check at all. The backfix register is the
 * authority for DEFECT FACTS AND IDS; the manifest is the authority for item
 * STATE. Nothing connected them. On 2026-09-15 the manifest was frozen at
 * 19:07 and the register kept growing until 19:57, and 29 not-fixed register
 * ids ended up in no queue item — fourteen of them in §1, which means they
 * reach an operator on today's release. A programmatic set difference found
 * it. Nothing in the loop would have.
 *
 * This gate is that set difference, run as a measurement.
 *
 * TWO ARMS, and the second is the one that keeps the register meaningful:
 *
 *   1. COVERAGE. Every not-fixed register id is named in the `register:` list
 *      of at least one manifest item. An id fixed on a backfix branch is
 *      covered too, because the work is the branch.
 *
 *   2. SECTION AGREEMENT. §1 means "present in what an operator runs today";
 *      §1b means pre-release. The manifest carries that as
 *      `ships_to_operators_today`. Where a covering item declares the field,
 *      it must agree with the section the id sits in. Widening §1's criterion
 *      — or quietly filing a §1 defect as pre-release work — is the one thing
 *      that would destroy the register's meaning, and it is exactly the kind
 *      of drift nobody notices by reading.
 *
 * §1c (CAP-xx, absent capabilities rather than defects) is exempt from arm 2:
 * it is neither section, and forcing a flag onto it would be inventing a fact.
 *
 * READS ONLY. It parses two files and shells out to the manifest's own Python
 * loader so that this gate and `queue-validate` can never disagree about what
 * the manifest says.
 *
 * Overrides, used by the non-vacuity ablation and by nothing else:
 *   --register <path>   --manifest <path>
 */

const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');
const { REPO_ROOT, report } = require('./_gate');

function argValue(flag, fallback) {
  const at = process.argv.indexOf(flag);
  return at > -1 && process.argv[at + 1] ? process.argv[at + 1] : fallback;
}

const REGISTER = argValue('--register',
  path.join(REPO_ROOT, 'docs', '30-design', 'remedial', 'nightscout-backfix-register.md'));
const MANIFEST = argValue('--manifest',
  path.join(REPO_ROOT, 'queue', 'work-queue.yaml'));

/* ---------------------------------------------------------------- register */
/*
 * The register is two tables with different column sets (§1 has a
 * `tenancy-independent` column that §1b lacks, §1c is headed `capability` and
 * `scope`), so the header row is parsed rather than assumed. A cell may carry
 * an escaped pipe — BF-60's does, `^22.23.2 \|\| ^24.20.0` — so the split is
 * on unescaped pipes only. Getting that wrong shifts a whole row's columns and
 * reads the severity cell as the status, which is how a fixed entry reads as
 * open.
 */
function parseRegister(text) {
  const entries = new Map();
  let section = null;
  let header = null;
  text.split('\n').forEach((line, index) => {
    const heading = line.match(/^##\s+(1b|1c|1|2b|2|3|4)\b/);
    if (line.startsWith('## ')) {
      section = heading ? heading[1] : null;
      header = null;
    }
    if (!line.trim().startsWith('|') || section === null) return;
    const cells = line.trim().replace(/^\|/, '').replace(/\|$/, '')
      .split(/(?<!\\)\|/).map((c) => c.trim());
    if (cells[0] && cells[0].toLowerCase() === 'id') {
      header = cells.map((c) => c.toLowerCase());
      return;
    }
    if (!header) return;
    const id = cells[0].replace(/[*`]/g, '');
    if (!/^(BF|CAP)-\d+$/.test(id)) return;
    const row = {};
    header.forEach((name, i) => { row[name] = cells[i] || ''; });
    if (!entries.has(id)) {
      entries.set(id, {
        id,
        section,
        line: index + 1,
        status: row.status || '',
        severity: row.severity || row.scope || '',
      });
    }
  });
  return entries;
}

/*
 * "not fixed" is decided by parsing the status column, never by grepping the
 * file for a word. DOC-EXPOSURE's first gate was `grep -q 'landed' <register>`
 * and it passed on the legend line and two unrelated uses of the word in
 * prose. The status cell is the only place the claim is made.
 *
 * `fixed` in this register means "repaired on a backfix branch, NOT MERGED" —
 * so a fixed id still reaches every operator. It is nonetheless COVERED for
 * this gate's purposes, because the branch carrying the repair is a queue item
 * and that is what coverage means here. Operator exposure is a different
 * question and DOC-EXPOSURE owns it.
 */
function isNotFixed(status) {
  const s = status.toLowerCase();
  if (/closed .*invalid|^\*\*closed/.test(s)) return false;
  if (/^\**fixed\b|^\**partly fixed\b|^\**fixed-in-seam\b/.test(s)) return false;
  return true;
}

/* ---------------------------------------------------------------- manifest */
/*
 * Loaded through the manifest's own PyYAML loader rather than re-parsed here.
 * A second parser is a second opinion about what the file says, and the two
 * would drift on the first block-style `register:` list somebody writes.
 */
const PY = `
import json, sys
sys.path.insert(0, ${JSON.stringify(path.join(REPO_ROOT, 'tools', 'queue'))})
import manifest
doc = manifest.load(${JSON.stringify(MANIFEST)})
print(json.dumps([{
    'id': i.get('id'),
    'parcel': i.get('parcel'),
    'register': i.get('register') or [],
    'ships': i.get('ships_to_operators_today'),
} for i in doc['items'] if isinstance(i, dict)]))
`;

let items;
try {
  items = JSON.parse(execFileSync('python3', ['-c', PY],
    { encoding: 'utf8', maxBuffer: 32 * 1024 * 1024, stdio: ['ignore', 'pipe', 'pipe'] }));
} catch (e) {
  report('register-queue-coverage', [{
    ok: false,
    text: `could not load ${path.relative(REPO_ROOT, MANIFEST)} through tools/queue/manifest.py: `
        + String(e.stderr || e.message).split('\n').filter(Boolean).slice(-1)[0],
  }]);
}

const register = parseRegister(fs.readFileSync(REGISTER, 'utf8'));
const findings = [];

/*
 * VACUITY GUARD. If either side parsed to nothing the gate is measuring
 * nothing, and a gate that examined nothing must not read as a pass. This is
 * not theoretical: the register's table shape has changed twice in a day.
 */
if (register.size === 0 || items.length === 0) {
  findings.push({
    ok: false,
    text: `parsed ${register.size} register entries and ${items.length} manifest items; `
        + 'one side has changed shape and this gate can no longer read it',
  });
  report('register-queue-coverage', findings);
}

const covered = new Map();      // register id -> [{item, ships}]
for (const item of items) {
  for (const id of item.register) {
    if (!covered.has(id)) covered.set(id, []);
    covered.get(id).push(item);
  }
}

const open = [...register.values()].filter((e) => isNotFixed(e.status));
findings.push({
  ok: true,
  text: `parsed ${register.size} register entries (${open.length} not fixed) `
      + `and ${items.length} manifest items carrying ${covered.size} distinct ids`,
});

/* --- arm 1: coverage ---------------------------------------------------- */
const uncovered = open.filter((e) => !covered.has(e.id));
for (const entry of uncovered) {
  findings.push({
    ok: false,
    text: `${entry.id} (§${entry.section}, register L${entry.line}, ${entry.status.slice(0, 40)}) `
        + 'is not fixed and no manifest item names it in `register:`',
  });
}
if (uncovered.length === 0) {
  findings.push({ ok: true, text: 'every not-fixed register id is named by at least one item' });
}

/* --- arm 2: section agreement ------------------------------------------- */
let checkedFlags = 0;
for (const entry of open) {
  if (entry.section === '1c') continue;          // neither §1 nor §1b; exempt
  const owners = covered.get(entry.id) || [];
  const declared = owners.filter((o) => typeof o.ships === 'boolean');
  if (declared.length === 0) continue;
  checkedFlags += 1;
  const expected = entry.section === '1';
  if (!declared.some((o) => o.ships === expected)) {
    findings.push({
      ok: false,
      text: `${entry.id} is §${entry.section} in the register but every item declaring it `
          + `(${declared.map((o) => `${o.id}=${o.ships}`).join(', ')}) says `
          + `ships_to_operators_today=${!expected}`,
    });
  }
}
findings.push({
  ok: true,
  text: `${checkedFlags} not-fixed ids had ships_to_operators_today declared; `
      + 'each was checked against its register section',
});

/* --- arm 3: the manifest must not invent ids ---------------------------- */
for (const [id, owners] of [...covered].sort()) {
  if (!register.has(id)) {
    findings.push({
      ok: false,
      text: `${id} is named by ${owners.map((o) => o.id).join(', ')} but is not in the register`,
    });
  }
}

report('register-queue-coverage', findings);
